diff --git a/wradlib/georef/polar.py b/wradlib/georef/polar.py
index f021e83..9ffea57 100644
--- a/wradlib/georef/polar.py
+++ b/wradlib/georef/polar.py
@@ -1136,9 +1136,8 @@ def georeference(obj, **kwargs):
     cf_by_axis = {c["axis"]: c for c in cf_coords}
     x_attrs = cf_by_axis.get("X")
     y_attrs = cf_by_axis.get("Y")
-    unit = x_attrs["units"]
-    z_attrs = {"standard_name": "height_above_ground", "units": unit}
-    gr_attrs = {"standard_name": "distance_from_radar", "units": unit}
+    z_attrs = {"standard_name": "height_above_ground", "units": "meters"}
+    gr_attrs = {"standard_name": "distance_from_radar", "units": "meters"}
     obj.coords["x"] = (dimlist, xyz[..., 0], x_attrs)
     obj.coords["y"] = (dimlist, xyz[..., 1], y_attrs)
     obj.coords["z"] = (dimlist, xyz[..., 2], z_attrs)

diff --git a/src/metpy/xarray.py b/src/metpy/xarray.py
index 111808a..917368f 100644
--- a/src/metpy/xarray.py
+++ b/src/metpy/xarray.py
@@ -1360,7 +1360,7 @@ def _wrap_output_like_matching_units(result, match):
             else units.Quantity(result, match_units)
         )
         return (
-            xr.DataArray(result, coords=match.coords, dims=match.dims) if output_xarray
+            xr.DataArray(result, coords=match.coords, dims=match.dims) if output_xarray and getattr(result, 'ndim', None) == len(match.dims)
             else result
         )

@@ -1379,7 +1379,7 @@ def _wrap_output_like_not_matching_units(result, match):
         result = units.Quantity(result)
     return (
         xr.DataArray(result, coords=match.coords, dims=match.dims)
-        if output_xarray and result is not None
+        if output_xarray and result is not None and getattr(result, 'ndim', None) == len(match.dims)
         else result
     )

diff --git a/satpy/readers/nwcsaf_nc.py b/satpy/readers/nwcsaf_nc.py
index ef68e83..f75c633 100644
--- a/satpy/readers/nwcsaf_nc.py
+++ b/satpy/readers/nwcsaf_nc.py
@@ -104,13 +104,16 @@ class NcNWCSAF(BaseFileHandler):

         try:
             # NWCSAF/Geo:
-            try:
-                kwrgs = {"sat_id": self.nc.attrs["satellite_identifier"]}
-            except KeyError:
-                kwrgs = {"sat_id": self.nc.attrs["satellite_identifier"].astype(str)}
+            sat_id = self.nc.attrs["satellite_identifier"]
+            if hasattr(sat_id, "item"):
+                sat_id = sat_id.item()
+            kwrgs = {"sat_id": str(sat_id)}
         except KeyError:
             # NWCSAF/PPS:
-            kwrgs = {"platform_name": self.nc.attrs["platform"]}
+            platform = self.nc.attrs["platform"]
+            if hasattr(platform, "item"):
+                platform = platform.item()
+            kwrgs = {"platform_name": str(platform)}

         self.set_platform_and_sensor(**kwrgs)

